# Full binding scan also catches old controls, incomplete/aborted invocations and
# helper paths that do not contain the question ID. No request is issued here.
binds=[]
for p in BASE.rglob('binding.json'):
    if p.is_relative_to(HERE):continue
    b=read(p)
    if b.get('question_id') not in ASSIGNED:continue
    inv=p.parent
    rs=[]
    for rp in sorted(inv.glob('run_*response.json')):rs.append({'path':str(rp),'sha256':file_hash(rp),'full_response':read(rp)})
    binds.append({'binding_path':str(p),'binding_sha256':file_hash(p),'binding':b,'all_invocation_files':{str(x):file_hash(x) for x in inv.iterdir() if x.is_file()},'full_raw_responses':rs})
write(HERE/'global_prior_binding_scan.json',{'created_at':now(),'scope_question_ids':ASSIGNED,'bindings':binds,'original_control_calls_reused':[],'interpretation':'Only one historical Plane276 invocation found; presetE both finalsD60 => MISS. Plane280 prior candidate was never called. No existing original controls found, none repeated. No additional matching question bindings or partial calls found outside own directory.'})
refs=[]
